# Extrait de configuration Nginx
# /etc/nginx/conf.d/app.conf
upstream apps {
    server 10.0.0.11:8080;
    server 10.0.0.12:8080;
}
server {
    listen 80;
    location / {
        proxy_pass http://apps;
        proxy_set_header Host $host;
    }
}

